param([Parameter(Mandatory=$true)][string]$AdminToken,[Parameter(Mandatory=$true)][string]$FineractUsername,[Parameter(Mandatory=$true)][string]$FineractPassword,[string]$KeycloakBaseUrl='http://127.0.0.1:19000',[string]$GatewayBaseUrl='http://127.0.0.1:18443',[string]$FineractBaseUrl='http://127.0.0.1:13000/fineract-provider')
$ErrorActionPreference='Stop'
$h=@{Authorization="Bearer $AdminToken";'Content-Type'='application/json'}
$realm='bank-customer';$uid=$null;$clientName=$null;$operatorId=$null;$operatorClient=$null;$transferId=$null;$corePosted=$false;$key="customer-transfer-e2e-$([guid]::NewGuid().ToString('N'))"
$beneficiaryId=[guid]::NewGuid()
try {
  $u='customer-transfer-'+[guid]::NewGuid().ToString('N').Substring(0,8);$p='Test1234!'
  Invoke-RestMethod -Method Post -Uri "$KeycloakBaseUrl/admin/realms/$realm/users" -Headers $h -Body (@{username=$u;enabled=$true;email="$u@example.test";emailVerified=$true;firstName='E2E';lastName='Customer';requiredActions=@();credentials=@(@{type='password';value=$p;temporary=$false})}|ConvertTo-Json -Depth 5)|Out-Null
  $uid=(Invoke-RestMethod -Uri "$KeycloakBaseUrl/admin/realms/$realm/users?username=$u" -Headers $h)[0].id
  $roles=@();foreach($roleName in @('CUSTOMER','CUSTOMER_MFA_VERIFIED')){try{$role=Invoke-RestMethod -Uri "$KeycloakBaseUrl/admin/realms/$realm/roles/$roleName" -Headers $h}catch{Invoke-RestMethod -Method Post -Uri "$KeycloakBaseUrl/admin/realms/$realm/roles" -Headers $h -Body (@{name=$roleName}|ConvertTo-Json)|Out-Null;$role=Invoke-RestMethod -Uri "$KeycloakBaseUrl/admin/realms/$realm/roles/$roleName" -Headers $h};$roles+=$role};$roleBody='['+(($roles|ForEach-Object{$_|ConvertTo-Json -Compress})-join ',')+']';Invoke-RestMethod -Method Post -Uri "$KeycloakBaseUrl/admin/realms/$realm/users/$uid/role-mappings/realm" -Headers $h -Body $roleBody|Out-Null
  $clientName='customer-transfer-client-'+[guid]::NewGuid().ToString('N').Substring(0,8)
  Invoke-RestMethod -Method Post -Uri "$KeycloakBaseUrl/admin/realms/$realm/clients" -Headers $h -Body (@{clientId=$clientName;enabled=$true;publicClient=$true;directAccessGrantsEnabled=$true;protocol='openid-connect'}|ConvertTo-Json)|Out-Null
  $token=(Invoke-RestMethod -Method Post -Uri "$KeycloakBaseUrl/realms/$realm/protocol/openid-connect/token" -ContentType 'application/x-www-form-urlencoded' -Body @{client_id=$clientName;grant_type='password';username=$u;password=$p}).access_token
  $ch=@{Authorization="Bearer $token";'Content-Type'='application/json'}
  $operatorUser='customer-transfer-operator-'+[guid]::NewGuid().ToString('N').Substring(0,8);$operatorPassword='Test1234!'
  Invoke-RestMethod -Method Post -Uri "$KeycloakBaseUrl/admin/realms/bank-internal/users" -Headers $h -Body (@{username=$operatorUser;enabled=$true;email="$operatorUser@example.test";emailVerified=$true;firstName='E2E';lastName='Operator';requiredActions=@();credentials=@(@{type='password';value=$operatorPassword;temporary=$false})}|ConvertTo-Json -Depth 5)|Out-Null
  $operatorId=(Invoke-RestMethod -Uri "$KeycloakBaseUrl/admin/realms/bank-internal/users?username=$operatorUser" -Headers $h)[0].id
  try{$operatorRole=Invoke-RestMethod -Uri "$KeycloakBaseUrl/admin/realms/bank-internal/roles/PAYMENT_OPERATOR" -Headers $h}catch{Invoke-RestMethod -Method Post -Uri "$KeycloakBaseUrl/admin/realms/bank-internal/roles" -Headers $h -Body (@{name='PAYMENT_OPERATOR'}|ConvertTo-Json)|Out-Null;$operatorRole=Invoke-RestMethod -Uri "$KeycloakBaseUrl/admin/realms/bank-internal/roles/PAYMENT_OPERATOR" -Headers $h}
  Invoke-RestMethod -Method Post -Uri "$KeycloakBaseUrl/admin/realms/bank-internal/users/$operatorId/role-mappings/realm" -Headers $h -Body ('['+($operatorRole|ConvertTo-Json -Compress)+']')|Out-Null
  $operatorClient='customer-transfer-operator-client-'+[guid]::NewGuid().ToString('N').Substring(0,8)
  Invoke-RestMethod -Method Post -Uri "$KeycloakBaseUrl/admin/realms/bank-internal/clients" -Headers $h -Body (@{clientId=$operatorClient;enabled=$true;publicClient=$true;directAccessGrantsEnabled=$true;protocol='openid-connect'}|ConvertTo-Json)|Out-Null
  $operatorToken=(Invoke-RestMethod -Method Post -Uri "$KeycloakBaseUrl/realms/bank-internal/protocol/openid-connect/token" -ContentType 'application/x-www-form-urlencoded' -Body @{client_id=$operatorClient;grant_type='password';username=$operatorUser;password=$operatorPassword}).access_token
  $operatorHeaders=@{Authorization="Bearer $operatorToken";'Content-Type'='application/json'}
  docker exec mifos-channel-bank-channel-postgres-1 psql -U bank_channel -d bank_channel -c "insert into customer_identity(subject,fineract_client_id) values('$uid',1);"|Out-Null
  docker exec mifos-channel-bank-channel-postgres-1 psql -U bank_channel -d bank_channel -c "insert into beneficiary(beneficiary_id,subject,account_token,account_last4,display_name,destination_account_id) values('$beneficiaryId','$uid','$('c'*64)','0002','Customer E2E beneficiary','2');"|Out-Null
  $me=Invoke-RestMethod -Uri "$GatewayBaseUrl/api/customer/v1/customers/me" -Headers $ch
  $accounts=Invoke-RestMethod -Uri "$GatewayBaseUrl/api/customer/v1/accounts" -Headers $ch
  if([string]::IsNullOrWhiteSpace($me.displayName) -or $accounts.items.Count -lt 1){throw 'Customer profile/account query failed'}
  $csvStatement=Invoke-WebRequest -UseBasicParsing -Uri "$GatewayBaseUrl/api/customer/v1/statements?accountId=1&format=csv" -Headers $ch
  $csvStatementReplay=Invoke-WebRequest -UseBasicParsing -Uri "$GatewayBaseUrl/api/customer/v1/statements?accountId=1&format=csv" -Headers $ch
  $pdfStatement=Invoke-WebRequest -UseBasicParsing -Uri "$GatewayBaseUrl/api/customer/v1/statements?accountId=1&format=pdf" -Headers $ch
  if($csvStatement.Headers['X-Statement-Balance-Check'] -ne 'True' -or $csvStatement.Content -ne $csvStatementReplay.Content -or $pdfStatement.Headers['Content-Type'] -notmatch 'application/pdf'){throw 'Statement balance, idempotency or PDF assertion failed'}
  $forbidden=0;try { Invoke-RestMethod -Method Post -Uri "$GatewayBaseUrl/api/customer/v1/transfers" -Headers ($ch+@{'Idempotency-Key'="$key-bad"}) -Body (@{sourceAccountId='2';beneficiaryId=$beneficiaryId.ToString();amount='1.00';currency='CNY'}|ConvertTo-Json)|Out-Null } catch {$forbidden=$_.Exception.Response.StatusCode.value__}
  $t=Invoke-RestMethod -Method Post -Uri "$GatewayBaseUrl/api/customer/v1/transfers" -Headers ($ch+@{'Idempotency-Key'=$key}) -Body (@{sourceAccountId='1';beneficiaryId=$beneficiaryId.ToString();amount='1.00';currency='CNY';reference='customer transfer'}|ConvertTo-Json)
  $transferId=$t.transferId;$posted=Invoke-RestMethod -Method Post -Uri "$GatewayBaseUrl/internal/transfers/$transferId/process" -Headers $operatorHeaders
  if($posted.status -ne 'SETTLED'){throw "Customer transfer did not settle: $($posted|ConvertTo-Json -Compress)"};$corePosted=$true
  $json=Invoke-RestMethod -Uri "$GatewayBaseUrl/api/customer/v1/transfers/$transferId/receipt?format=json" -Headers $ch
  $pdf=Invoke-WebRequest -UseBasicParsing -Uri "$GatewayBaseUrl/api/customer/v1/transfers/$transferId/receipt?format=pdf" -Headers $ch
  $notes=Invoke-RestMethod -Uri "$GatewayBaseUrl/api/customer/v1/notifications" -Headers $ch
  if($forbidden -ne 403 -or $posted.status -ne 'SETTLED' -or $json.sha256.Length -ne 64 -or $pdf.Headers['Content-Type'] -notmatch 'application/pdf' -or $notes.items.Count -lt 1){throw 'Customer transfer assertions failed'}
  Write-Output "CUSTOMER_READ=PASS STATEMENT=PASS STATEMENT_IDEMPOTENCY=PASS CUSTOMER_TRANSFER=PASS ownership403=PASS settled=PASS receiptJson=PASS receiptPdf=PASS notification=PASS transferId=$transferId"
} finally {
  if($transferId){docker exec mifos-channel-bank-channel-postgres-1 psql -U bank_channel -d bank_channel -c "delete from transfer_receipt where transfer_id='$transferId';delete from notification where subject='$uid';delete from outbox_event where aggregate_id='$transferId';delete from transfer_accounting_projection where transfer_id='$transferId';delete from transfer_state_history where transfer_id='$transferId';delete from transfer_order where transfer_id='$transferId';delete from idempotency_record where idempotency_key like 'customer-transfer-e2e-%';"|Out-Null}
  if($corePosted){$cleanupBody='{"fromAccountId":2,"toAccountId":1,"transferAmount":1.00,"transferDate":"2026-07-10","fromAccountType":2,"toAccountType":2,"fromOfficeId":1,"fromClientId":2,"toOfficeId":1,"toClientId":1,"transferDescription":"Customer E2E compensation","locale":"en","dateFormat":"yyyy-MM-dd","currencyCode":"CNY"}';$compKey="customer-comp-$([guid]::NewGuid().ToString('N').Substring(0,20))";$basic=[Convert]::ToBase64String([Text.Encoding]::ASCII.GetBytes("${FineractUsername}:${FineractPassword}"));Invoke-RestMethod -Method Post -Uri "$FineractBaseUrl/api/v1/accounttransfers" -Headers @{Authorization="Basic $basic";'Fineract-Platform-TenantId'='default';'Content-Type'='application/json';'Idempotency-Key'=$compKey} -Body $cleanupBody|Out-Null}
  if($uid){docker exec mifos-channel-bank-channel-postgres-1 psql -U bank_channel -d bank_channel -c "delete from beneficiary where beneficiary_id='$beneficiaryId';delete from customer_identity where subject='$uid';"|Out-Null;Invoke-RestMethod -Method Delete -Uri "$KeycloakBaseUrl/admin/realms/$realm/users/$uid" -Headers $h|Out-Null}
  if($clientName){$cs=Invoke-RestMethod -Uri "$KeycloakBaseUrl/admin/realms/$realm/clients?clientId=$clientName" -Headers $h;foreach($c in $cs){Invoke-RestMethod -Method Delete -Uri "$KeycloakBaseUrl/admin/realms/$realm/clients/$($c.id)" -Headers $h|Out-Null}}
  if($operatorId){Invoke-RestMethod -Method Delete -Uri "$KeycloakBaseUrl/admin/realms/bank-internal/users/$operatorId" -Headers $h|Out-Null}
  if($operatorClient){$cs=Invoke-RestMethod -Uri "$KeycloakBaseUrl/admin/realms/bank-internal/clients?clientId=$operatorClient" -Headers $h;foreach($c in $cs){Invoke-RestMethod -Method Delete -Uri "$KeycloakBaseUrl/admin/realms/bank-internal/clients/$($c.id)" -Headers $h|Out-Null}}
}
